class InstanceServiceSync(Protocol):
    """
    Service for managing SoulFire instances.
    An instance is a permission and configuration compartment for independently
    controlled Minecraft bots, settings, accounts, proxies, and remote clients.

    All operations require appropriate permissions:
    - CREATE_INSTANCE (global): Required to create new instances
    - READ_INSTANCE: Required to list and view instance details
    - UPDATE_INSTANCE_META: Required to change instance name/icon
    - UPDATE_INSTANCE_CONFIG: Required to modify settings, accounts, and proxies
    - DELETE_INSTANCE: Required to delete an instance
    - READ_INSTANCE_AUDIT_LOGS: Required to view audit logs
    - READ_BOT_INFO: Required to read account metadata
    """
    def get_or_create_instance(self, request: InstanceGetOrCreateRequest, ctx: RequestContext[InstanceGetOrCreateRequest, InstanceGetOrCreateResponse], /) -> InstanceGetOrCreateResponse:
        """
        Gets or creates an instance owned by the caller without a list/create race.
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def get_or_create_bot(self, request: InstanceGetOrCreateBotRequest, ctx: RequestContext[InstanceGetOrCreateBotRequest, InstanceGetOrCreateBotResponse], /) -> InstanceGetOrCreateBotResponse:
        """
        Gets or creates a named bot account. Does not change its desired state.
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def create_instance(self, request: InstanceCreateRequest, ctx: RequestContext[InstanceCreateRequest, InstanceCreateResponse], /) -> InstanceCreateResponse:
        """
        Creates a new instance with the given friendly name.
        Requires: CREATE_INSTANCE global permission
        Returns: The UUID of the newly created instance
        Errors: INTERNAL if creation fails
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def duplicate_instance(self, request: InstanceDuplicateRequest, ctx: RequestContext[InstanceDuplicateRequest, InstanceDuplicateResponse], /) -> InstanceDuplicateResponse:
        """
        Copies the source configuration and icon into a new instance in one write.
        Includes accounts, proxies, and persistent metadata. Bots start stopped.
        Does not copy permissions, files, scripts, audit logs, or runtime state.
        Requires: CREATE_INSTANCE globally and READ_INSTANCE on the source.
        Errors: INVALID_ARGUMENT for invalid input, NOT_FOUND for a missing source.
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def delete_instance(self, request: InstanceDeleteRequest, ctx: RequestContext[InstanceDeleteRequest, InstanceDeleteResponse], /) -> InstanceDeleteResponse:
        """
        Permanently deletes an instance and all its data.
        Connected bots are stopped before the instance is deleted.
        This operation cannot be undone.
        Requires: DELETE_INSTANCE permission on the instance
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def list_instances(self, request: InstanceListRequest, ctx: RequestContext[InstanceListRequest, InstanceListResponse], /) -> InstanceListResponse:
        """
        Lists all instances the current user has permission to view.
        Only instances where the user has READ_INSTANCE permission are returned.
        Returns summary information for each instance.
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def get_instance_info(self, request: InstanceInfoRequest, ctx: RequestContext[InstanceInfoRequest, InstanceInfoResponse], /) -> InstanceInfoResponse:
        """
        Gets detailed information about a specific instance.
        Supports conditional requests via if_modified_since to reduce bandwidth.
        Requires: READ_INSTANCE permission on the instance
        Returns: Full instance info or not_modified status
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def update_instance_meta(self, request: InstanceUpdateMetaRequest, ctx: RequestContext[InstanceUpdateMetaRequest, InstanceUpdateMetaResponse], /) -> InstanceUpdateMetaResponse:
        """
        Updates instance metadata (friendly name or icon).
        Only one field can be updated per request.
        Requires: UPDATE_INSTANCE_META permission on the instance
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def update_instance_config(self, request: InstanceUpdateConfigRequest, ctx: RequestContext[InstanceUpdateConfigRequest, InstanceUpdateConfigResponse], /) -> InstanceUpdateConfigResponse:
        """
        Replaces the entire instance configuration.
        Used primarily for profile import operations.
        For individual setting changes, use UpdateInstanceConfigEntry instead.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def update_instance_config_entry(self, request: InstanceUpdateConfigEntryRequest, ctx: RequestContext[InstanceUpdateConfigEntryRequest, InstanceUpdateConfigEntryResponse], /) -> InstanceUpdateConfigEntryResponse:
        """
        Updates a single configuration entry by namespace and key.
        More efficient than UpdateInstanceConfig for individual changes.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def add_instance_account(self, request: InstanceAddAccountRequest, ctx: RequestContext[InstanceAddAccountRequest, InstanceAddAccountResponse], /) -> InstanceAddAccountResponse:
        """
        Adds a Minecraft account to the instance.
        The account's profile_id must be unique within the instance.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def remove_instance_account(self, request: InstanceRemoveAccountRequest, ctx: RequestContext[InstanceRemoveAccountRequest, InstanceRemoveAccountResponse], /) -> InstanceRemoveAccountResponse:
        """
        Removes a Minecraft account from the instance by profile_id.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def update_instance_account(self, request: InstanceUpdateAccountRequest, ctx: RequestContext[InstanceUpdateAccountRequest, InstanceUpdateAccountResponse], /) -> InstanceUpdateAccountResponse:
        """
        Updates an existing Minecraft account in the instance.
        The account is matched by profile_id and replaced.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def add_instance_accounts_batch(self, request: InstanceAddAccountsBatchRequest, ctx: RequestContext[InstanceAddAccountsBatchRequest, InstanceAddAccountsBatchResponse], /) -> InstanceAddAccountsBatchResponse:
        """
        Adds multiple Minecraft accounts to the instance in a single operation.
        More efficient than multiple AddInstanceAccount calls.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def replace_instance_accounts(self, request: InstanceReplaceAccountsRequest, ctx: RequestContext[InstanceReplaceAccountsRequest, InstanceReplaceAccountsResponse], /) -> InstanceReplaceAccountsResponse:
        """
        Atomically replaces the account list and stops bots whose accounts were removed.
        Other instance configuration remains unchanged.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if the instance does not exist; INVALID_ARGUMENT for invalid accounts
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def remove_instance_accounts_batch(self, request: InstanceRemoveAccountsBatchRequest, ctx: RequestContext[InstanceRemoveAccountsBatchRequest, InstanceRemoveAccountsBatchResponse], /) -> InstanceRemoveAccountsBatchResponse:
        """
        Removes multiple Minecraft accounts from the instance by their profile_ids.
        More efficient than multiple RemoveInstanceAccount calls.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def add_instance_proxy(self, request: InstanceAddProxyRequest, ctx: RequestContext[InstanceAddProxyRequest, InstanceAddProxyResponse], /) -> InstanceAddProxyResponse:
        """
        Adds a proxy to the instance.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def remove_instance_proxy(self, request: InstanceRemoveProxyRequest, ctx: RequestContext[InstanceRemoveProxyRequest, InstanceRemoveProxyResponse], /) -> InstanceRemoveProxyResponse:
        """
        Removes a proxy from the instance by its index.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if instance does not exist
        Errors: INVALID_ARGUMENT if index is out of bounds
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def update_instance_proxy(self, request: InstanceUpdateProxyRequest, ctx: RequestContext[InstanceUpdateProxyRequest, InstanceUpdateProxyResponse], /) -> InstanceUpdateProxyResponse:
        """
        Updates an existing proxy in the instance by its index.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if instance does not exist
        Errors: INVALID_ARGUMENT if index is out of bounds
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def add_instance_proxies_batch(self, request: InstanceAddProxiesBatchRequest, ctx: RequestContext[InstanceAddProxiesBatchRequest, InstanceAddProxiesBatchResponse], /) -> InstanceAddProxiesBatchResponse:
        """
        Adds multiple proxies to the instance in a single operation.
        More efficient than multiple AddInstanceProxy calls.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

    def remove_instance_proxies_batch(self, request: InstanceRemoveProxiesBatchRequest, ctx: RequestContext[InstanceRemoveProxiesBatchRequest, InstanceRemoveProxiesBatchResponse], /) -> InstanceRemoveProxiesBatchResponse:
        """
        Removes multiple proxies from the instance by their addresses.
        More efficient than multiple RemoveInstanceProxy calls.
        Requires: UPDATE_INSTANCE_CONFIG permission on the instance
        Errors: NOT_FOUND if instance does not exist
        """
        raise ConnectError(Code.UNIMPLEMENTED, 'Not implemented')

